do $$declare definition text;begin select pg_get_functiondef('private.advice_command(text,jsonb)'::regprocedure) into definition;definition:=replace(definition,'if me.user_id is null then raise exception ''ADVICE_PROFILE''; end if;','if me.user_id is null and p_action not in (''review'',''resolve'',''suspend'') then raise exception ''ADVICE_PROFILE''; end if;');execute definition;end$$;